/**
 * Adapts a Next.js `searchParams` record to the codec. Repeated keys
 * (`?status=todo&status=done`) are read as one comma list.
 */
export function readableSearchParams(
  record: Readonly<Record<string, string | string[] | undefined>>,
): ReadableParams {
  return {
    get(name: string): string | null {
      const value = record[name];
      if (value === undefined) return null;
      return Array.isArray(value) ? value.join(",") : value;
    },
  };
}
