cd /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/7e7896bd-d356-4549-8d8e-5a0ae86b15b8; cat > tests/repositories/zz-tmp-filters.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { issueFilterSchema } from "@/schemas/issue";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("tmp-x");
  const mk = async (o: any) => issueRepo.insertIssue(issueInput(t.org.id, t.project.id, o), t.userIds.owner, await issueRepo.nextIssueNumber(t.org.id, t.project.id));
  const a = await mk({ title: "aaa", assigneeId: t.userIds.member, dueAt: "2026-03-02T15:00:00.000Z" });
  const b = await mk({ title: "bbb", dueAt: "2026-03-03T00:00:00.000Z" });
  const c = await mk({ title: "ccc" });
  const l1 = await labelRepo.insertLabel({ orgId: t.org.id, name: "x", color: "#000000", description: null } as any);
  const l2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "y", color: "#000000", description: null } as any);
  await labelRepo.setIssueLabels(t.org.id, a.id, [l1.id, l2.id]);
  await labelRepo.setIssueLabels(t.org.id, b.id, [l1.id]);
  await issueRepo.archiveIssue(t.org.id, c.id);
  const q = async (f: any) => { const p = await issueRepo.listIssues(issueFilterSchema.parse({ orgId: t.org.id, ...f })); return [p.items.map((i) => i.title).sort().join(","), p.total]; };
  expect(await q({ assigneeId: null })).toEqual(["bbb", 1]);
  expect(await q({ labelIds: [l1.id, l2.id] })).toEqual(["aaa", 1]);
  expect(await q({ dueBefore: "2026-03-02" })).toEqual(["aaa", 1]);
  expect(await q({ dueBefore: "2026-03-02T15:00:00Z" })).toEqual(["", 0]);
  expect(await q({ status: ["open"] })).toEqual(["aaa,bbb", 2]);
  expect(await q({ status: ["closed"] })).toEqual(["", 0]);
  expect(await q({ archivedOnly: true })).toEqual(["ccc", 1]);
  expect(await q({ includeArchived: true })).toEqual(["aaa,bbb,ccc", 3]);
});
EOF
npx vitest run tests/repositories/zz-tmp-filters.test.ts 2>&1 | grep -v "npm warn" | tail -30; rm tests/repositories/zz-tmp-filters.test.ts

